"""Lab-report and DNA imports: shared genomics importer, web upload endpoints, CLI vault path."""
import json
import sys
import zipfile

import pytest

from test_health_hub_extensions import _promethease_zip
from uniscale import cli, genomics

ANCESTRY_TXT = (
    "#AncestryDNA raw data download\n"
    "rsid\tchromosome\tposition\tallele1\tallele2\n"
    "rs429358\t19\t44908684\tT\tT\n"
    "rs7412\t19\t44908822\tC\tC\n"
    "rs762551\t15\t74749576\tA\tC\n"
)
TWENTYTHREE_TXT = (
    "# This data file generated by 23andMe\n"
    "# rsid\tchromosome\tposition\tgenotype\n"
    "rs429358\t19\t44908684\tTT\n"
    "rs7412\t19\t44908822\tCC\n"
    "rs762551\t15\t74749576\tAC\n"
)
MYHERITAGE_CSV = (
    "# MyHeritage DNA raw data.\n"
    "RSID,CHROMOSOME,POSITION,RESULT\n"
    '"rs429358","19","44908684","TT"\n'
    '"rs7412","19","44908822","CC"\n'
    '"rs762551","15","74749576","AC"\n'
)


def _zip(path, name, text):
    with zipfile.ZipFile(path, "w") as z:
        z.writestr(name, text)
    return str(path)


def _genomics_lines(db):
    return [json.loads(l) for l in db.read_text().splitlines() if '"genomics"' in l]


@pytest.mark.parametrize("name,text", [
    ("AncestryDNA.txt", ANCESTRY_TXT),
    ("genome_Jane_Doe_v5_Full.txt", TWENTYTHREE_TXT),
    ("MyHeritage_raw_dna_data.csv", MYHERITAGE_CSV),
])
def test_import_dna_file_reads_each_vendor_zip_and_text(tmp_path, name, text):
    db = tmp_path / "db.jsonl"
    (tmp_path / name).write_text(text)
    for path in (_zip(tmp_path / "raw.zip", name, text), str(tmp_path / name)):
        prof = genomics.import_dna_file(path, db_path=str(db))
        assert "ε3/ε3" in prof["key_highlights"]["apoe_isoform"]
        assert "Intermediate" in prof["key_highlights"]["caffeine_metabolism"]
    assert len(_genomics_lines(db)) == 2


def test_import_dna_file_rejects_unreadable_files_without_writing(tmp_path):
    db = tmp_path / "db.jsonl"
    junk_zip = _zip(tmp_path / "junk.zip", "readme.md", "nothing here")
    junk_txt = tmp_path / "junk.txt"
    junk_txt.write_text("hello\nworld\n")
    for path in (junk_zip, str(junk_txt)):
        with pytest.raises(ValueError):
            genomics.import_dna_file(path, db_path=str(db))
    assert not db.exists()


@pytest.fixture
def client(tmp_path, monkeypatch):
    from fastapi.testclient import TestClient
    from uniscale import server
    db = tmp_path / "vault.jsonl"
    monkeypatch.setenv("UNISCALE_DB_PATH", str(db))
    monkeypatch.setattr(server.config.server, "api_token", None)
    return TestClient(server.app), db


def test_upload_dna_raw_text_and_ignores_empty_optional_fields(client):
    c, db = client
    # Browsers send unselected <input type=file> fields as empty parts with filename="".
    res = c.post("/api/import/dna", files={
        "file": ("genome_23andme.txt", TWENTYTHREE_TXT.encode(), "text/plain"),
        "father": ("", b"", "application/octet-stream"),
        "mother": ("", b"", "application/octet-stream"),
        "ancestry": ("", b"", "application/octet-stream"),
    })
    assert res.status_code == 201, res.text
    assert res.json()["snps_found"] == 3
    assert len(_genomics_lines(db)) == 1


def test_upload_dna_trio_with_same_named_zips(client, tmp_path):
    c, db = client
    zips = {}
    for role, genos in {
        "file": {"rs429358": "TT", "rs7412": "CC", "rs762551": "AA"},
        "father": {"rs429358": "TT", "rs7412": "CT", "rs762551": "AC"},
        "mother": {"rs429358": "CT", "rs7412": "CC", "rs762551": "AA"},
    }.items():
        with open(_promethease_zip(tmp_path / f"{role}.zip", genos), "rb") as f:
            zips[role] = f.read()
    res = c.post("/api/import/dna", files={
        role: ("promethease.zip", data, "application/zip") for role, data in zips.items()
    })
    assert res.status_code == 201, res.text
    assert res.json()["trio_status"]["is_phased_trio"] is True
    assert _genomics_lines(db)[-1]["trio_insights"]


def test_upload_dna_rejects_garbage(client):
    c, db = client
    res = c.post("/api/import/dna", files={"file": ("x.zip", b"not a zip", "application/zip")})
    assert res.status_code == 422
    assert "Could not import DNA file" in res.json()["detail"]
    assert not db.exists()


def test_upload_lab_json(client):
    c, db = client
    report = {
        "timestamp": "2026-03-01T14:30:00+00:00",
        "lab_name": "Quest Diagnostics",
        "markers": {"hdl_cholesterol": {"name": "HDL Cholesterol", "value": 62, "unit": "mg/dL"}},
    }
    res = c.post("/api/import/lab", files={"file": ("labs.json", json.dumps(report).encode(), "application/json")})
    assert res.status_code == 201, res.text
    assert res.json()["total_markers"] == 1
    saved = [json.loads(l) for l in db.read_text().splitlines()]
    assert saved[0]["type"] == "blood_test" and saved[0]["markers"]["hdl_cholesterol"]["value"] == 62


def test_upload_lab_rejects_unsupported_file(client):
    c, _ = client
    res = c.post("/api/import/lab", files={"file": ("labs.txt", b"hello", "text/plain")})
    assert res.status_code == 422


OMRON_CSV = "Date,Time,Systolic (mmHg),Diastolic (mmHg),Pulse (bpm)\n2026-03-01,08:00:00,121,79,62\n2026-03-02,08:05:00,118,77,60\n"


def test_upload_device_csv_detects_omron(client):
    c, db = client
    res = c.post("/api/import/csv", files={"file": ("omron.csv", OMRON_CSV.encode(), "text/csv")})
    assert res.status_code == 201, res.text
    assert res.json()["blood_pressure_found"] == 2
    assert [json.loads(l)["systolic"] for l in db.read_text().splitlines()] == [121, 118]


def test_upload_device_rejects_unknown_source_and_unreadable_files(client):
    c, db = client
    assert c.post("/api/import/fitbit", files={"file": ("x.csv", b"a,b", "text/csv")}).status_code == 404
    res = c.post("/api/import/csv", files={"file": ("x.csv", b"just,some\nrandom,text\n", "text/csv")})
    assert res.status_code == 422 and "Fitdays or Omron" in res.json()["detail"]
    res = c.post("/api/import/garmin", files={"file": ("export.zip", b"not a zip", "application/zip")})
    assert res.status_code == 422
    res = c.post("/api/import/vesync", files={"file": ("v.json", b"[]", "application/json")})
    assert res.status_code == 422 and "No records" in res.json()["detail"]
    assert not db.exists()
    # Upload scratch dirs are created next to the vault (not tmpfs /tmp) and cleaned up.
    assert not [p for p in db.parent.iterdir() if p.name.startswith(".import-")]


def test_no_module_hardcodes_the_default_vault_path():
    import pathlib
    import uniscale
    offenders = [
        str(p) for p in pathlib.Path(uniscale.__file__).parent.rglob("*.py")
        if "config/uniscale/measurements.jsonl" in p.read_text()
    ]
    assert offenders == []


def test_library_defaults_follow_configured_data_dir(tmp_path, monkeypatch):
    from uniscale.config import vault_db_path
    from uniscale.importer import save_history
    from uniscale.models import BloodPressureMeasurement
    data_dir = tmp_path / "data"
    cfg = tmp_path / "config.toml"
    cfg.write_text(f'[general]\ndata_dir = "{data_dir}"\n')
    monkeypatch.setenv("UNISCALE_CONFIG", str(cfg))
    monkeypatch.delenv("UNISCALE_DB_PATH", raising=False)

    assert vault_db_path() == str(data_dir / "measurements.jsonl")
    save_history([BloodPressureMeasurement(systolic=120, diastolic=80, pulse=60)])
    assert (data_dir / "measurements.jsonl").exists()

    monkeypatch.setenv("UNISCALE_DB_PATH", str(tmp_path / "override.jsonl"))
    assert vault_db_path() == str(tmp_path / "override.jsonl")


def test_cli_imports_write_to_configured_data_dir(tmp_path, monkeypatch, capsys):
    monkeypatch.delenv("UNISCALE_CONFIG", raising=False)
    monkeypatch.delenv("UNISCALE_DB_PATH", raising=False)
    monkeypatch.setenv("HOME", str(tmp_path / "home"))
    data_dir = tmp_path / "data"
    cfg = tmp_path / "config.toml"
    cfg.write_text(f'[general]\ndata_dir = "{data_dir}"\n')
    dna = tmp_path / "genome.txt"
    dna.write_text(TWENTYTHREE_TXT)
    lab = tmp_path / "labs.json"
    lab.write_text(json.dumps({"lab_name": "Quest Diagnostics", "markers": {"tsh": {"name": "TSH", "value": 1.2}}}))

    omron = tmp_path / "omron.csv"
    omron.write_text(OMRON_CSV)

    for argv in (["genomics", "import", str(dna)], ["import-lab", str(lab)], ["import-csv", str(omron)]):
        monkeypatch.setattr(sys, "argv", ["uniscale", "-c", str(cfg), *argv])
        cli.main()

    types = [json.loads(l)["type"] for l in (data_dir / "measurements.jsonl").read_text().splitlines()]
    assert types == ["genomics", "blood_test", "blood_pressure", "blood_pressure"]
    assert not (tmp_path / "home" / ".config" / "uniscale" / "measurements.jsonl").exists()

    monkeypatch.setattr(sys, "argv", ["uniscale", "-c", str(cfg), "genomics", "report"])
    cli.main()
    assert "ε3/ε3" in capsys.readouterr().out
